import{_ as r}from"./plugin-vue_export-helper-c27b6911.js";import{r as s,o as l,c as o,a,b as e,e as n,f as t}from"./app-99582225.js";const c="/assets/image-20230221141110913-b6466226.png",d="/assets/image-20230221150411253-fb315ece.png",p="/assets/image-20230221150441578-0606ee27.png",g="/assets/image-20230221150539110-3f2a12c3.png",h="/assets/image-20230221150603746-f085a4b5.png",f="/assets/image-20230221150626389-2757cd9d.png",u="/assets/image-20230221150722223-24a4e260.png",m="/assets/image-20230221151317195-e2de329d.png",_="/assets/image-20230221151359102-dd840d0a.png",b="/assets/image-20230221151419132-7e67cac9.png",L="/assets/image-20230221151436675-65c3a15f.png",x="/assets/image-20230221151510565-a5753125.png",S="/assets/image-20230221151528892-33e91496.png",E="/assets/image-20230221151551557-af49f996.png",C="/assets/image-20230221151721336-603efbfb.png",O="/assets/image-20230221151750803-d4f0c6cc.png",T="/assets/image-20230221151808936-bb46ffa3.png",y="/assets/image-20230221151839422-c13904a4.png",z="/assets/image-20230221151929075-58f7dc19.png",A="/assets/image-20230221151954378-8a581cbf.png",q="/assets/image-20230221152012223-fb9ae23e.png",N="/assets/image-20230221152025423-1de899bb.png",Q="/assets/image-20230221152052607-98f438ac.png",R="/assets/image-20230221152115563-15fb6095.png",B="/assets/image-20230221152142413-2c412e13.png",U="/assets/image-20230221152224235-1b5926ca.png",k="/assets/image-20230221152313875-90207e23.png",w="/assets/image-20230221152329434-8867ef6c.png",I="/assets/image-20230221152439943-d9c73060.png",P="/assets/image-20230221152500479-56f50ba9.png",v="/assets/image-20230221152526930-dfa6b5ed.png",D={},M=a("h1",{id:"plsql优化",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#plsql优化","aria-hidden":"true"},"#"),e(" PLSQL优化")],-1),V={href:"https://blog.csdn.net/lifetragedy/article/details/51013069",target:"_blank",rel:"noopener noreferrer"},F={href:"https://so.csdn.net/so/search?q=SQL%E8%AF%AD%E5%8F%A5&spm=1001.2101.3001.7020",target:"_blank",rel:"noopener noreferrer"},H=t('<h2 id="优化的理论基础" tabindex="-1"><a class="header-anchor" href="#优化的理论基础" aria-hidden="true">#</a> 优化的理论基础</h2><figure><img src="'+c+'" alt="优化理论基础" tabindex="0" loading="lazy"><figcaption>优化理论基础</figcaption></figure><h2 id="通过select-count-进入优化之旅" tabindex="-1"><a class="header-anchor" href="#通过select-count-进入优化之旅" aria-hidden="true">#</a> 通过Select Count(?)进入优化之旅</h2><p>不看百度或者GOOGLE说出下面3者的区别？</p><p>SELECT COUNT (*)</p><p>SELECT COUNT(1)</p><p>SELECT COUNT(字段名）</p><h3 id="select-count-的知识" tabindex="-1"><a class="header-anchor" href="#select-count-的知识" aria-hidden="true">#</a> SELECT COUNT(?) 的知识</h3><blockquote><p>原文此处解释应是有误，秋迟放上正确理解：</p></blockquote>',9),W=a("p",null,[e("SELECT COUNT (*) 与 SELECT COUNT(1) 都可"),a("strong",null,"以统计表中行数"),e("，"),a("strong",null,"二者没啥太大区别"),e("，除了 COUNT(1) 会把“1”这个文字附加到“FROM”查出的每个列后面。")],-1),G=a("em",null,"把“1”这个文字附加到“FROM”查出的每个列后面",-1),J=a("em",null,"统计附加完“1”的列",-1),j=a("br",null,null,-1),X={href:"https://www.techtarget.com/searchoracle/answer/COUNT-or-COUNT-1",target:"_blank",rel:"noopener noreferrer"},K=a("li",null,[a("p",null,[e("SELECT COUNT(字段名）："),a("strong",null,"如果该字段有 NULL 值则不计数")])],-1),Y=a("blockquote",null,[a("p",null,"COUNT() 有两个非常不同的作用："),a("ul",null,[a("li",null,[a("p",null,"它可以统计某个列值的数量，也可以统计行数。在统计列值时要求列值是非空的（不统计 NULL）。如果在 COUNT() 的括号中定了列或者列表达式，则统计的就是这个表达式有值的结果数。")]),a("li",null,[a("p",null,"COUNT() 的另一个作用是统计结果集的行数。当 MySQL 确认括号内的表达式值不可能为空时，实际上就是在统计行数。最简单的就是当我们使用COUNT(*)的时候，这种情况下通配符 * 并不像我们猜想的那样扩展成所有的列，实际上，他会忽略所有列而直接统计所有的行数。"),a("p",null,"——《高性能MySQL》。")])])],-1),Z={href:"https://learnsql.com/blog/difference-between-count-distinct/",target:"_blank",rel:"noopener noreferrer"},$=t('<h2 id="oracle的优化器" tabindex="-1"><a class="header-anchor" href="#oracle的优化器" aria-hidden="true">#</a> ORACLE的优化器</h2><p>要说 PLSQL 优化，我们先需要来好好说一下 Oracle 优化器的知识：</p><figure><img src="'+d+'" alt="Oracle 优化器" tabindex="0" loading="lazy"><figcaption>Oracle 优化器</figcaption></figure><h3 id="优化器的优化模式" tabindex="-1"><a class="header-anchor" href="#优化器的优化模式" aria-hidden="true">#</a> 优化器的优化模式</h3><figure><img src="'+p+'" alt="优化模式" tabindex="0" loading="lazy"><figcaption>优化模式</figcaption></figure><h3 id="cbo模式" tabindex="-1"><a class="header-anchor" href="#cbo模式" aria-hidden="true">#</a> CBO模式</h3><figure><img src="'+g+'" alt="CBO模式" tabindex="0" loading="lazy"><figcaption>CBO模式</figcaption></figure><h3 id="rbo模式" tabindex="-1"><a class="header-anchor" href="#rbo模式" aria-hidden="true">#</a> RBO模式</h3><figure><img src="'+h+'" alt="RBO模式" tabindex="0" loading="lazy"><figcaption>RBO模式</figcaption></figure><h3 id="一起来看看oracle优化器的发展历程" tabindex="-1"><a class="header-anchor" href="#一起来看看oracle优化器的发展历程" aria-hidden="true">#</a> 一起来看看oracle优化器的发展历程</h3><figure><img src="'+f+'" alt="oracle优化器的发展历程" tabindex="0" loading="lazy"><figcaption>oracle优化器的发展历程</figcaption></figure><p>所以，我们知道 ORACLE10 后开始默认使用 CBO，在 CBO 时 ORACLE 会自动来选择最优的执行计划，有时我们会认为：这个应该走索引更好啊，但是对于 CBO 来说，一个 FULL TABLE ACCESS 反而比索引更有效。</p><p>因此，在CBO的模式下，我们需要做的就是：</p><ol><li>做好数据库信息的相关统计</li><li>合理建设我们的索引</li><li>优化我们的SQL</li></ol><h2 id="让我们从索引的基本知识下手吧" tabindex="-1"><a class="header-anchor" href="#让我们从索引的基本知识下手吧" aria-hidden="true">#</a> 让我们从索引的基本知识下手吧</h2><p>索引是不需要修改SQL最直接带来性能提升的利器，何时该建索引，怎么建？怎么样让你的索引更合理？</p><h3 id="索引按内部结构分类" tabindex="-1"><a class="header-anchor" href="#索引按内部结构分类" aria-hidden="true">#</a> 索引按内部结构分类</h3><figure><img src="'+u+'" alt="索引按内部结构分类" tabindex="0" loading="lazy"><figcaption>索引按内部结构分类</figcaption></figure><h3 id="索引按功能分类" tabindex="-1"><a class="header-anchor" href="#索引按功能分类" aria-hidden="true">#</a> 索引按功能分类</h3><figure><img src="'+m+'" alt="索引按功能分类" tabindex="0" loading="lazy"><figcaption>索引按功能分类</figcaption></figure><h3 id="索引按索引对象分类" tabindex="-1"><a class="header-anchor" href="#索引按索引对象分类" aria-hidden="true">#</a> 索引按索引对象分类</h3><figure><img src="'+_+'" alt="索引按索引对象分类" tabindex="0" loading="lazy"><figcaption>索引按索引对象分类</figcaption></figure><h3 id="建立索引的方法论" tabindex="-1"><a class="header-anchor" href="#建立索引的方法论" aria-hidden="true">#</a> 建立索引的方法论</h3><p>上面介绍了这么多索引的分类，下面来讲讲建立索引的方法论吧，大家可能较关心这个，因为这个是经验总结也是实战有用的利器哈。</p><figure><img src="'+b+'" alt="建立索引的方法论1" tabindex="0" loading="lazy"><figcaption>建立索引的方法论1</figcaption></figure><figure><img src="'+L+'" alt="建立索引的方法论2" tabindex="0" loading="lazy"><figcaption>建立索引的方法论2</figcaption></figure><h3 id="不建议建立索引的情况" tabindex="-1"><a class="header-anchor" href="#不建议建立索引的情况" aria-hidden="true">#</a> 不建议建立索引的情况</h3><p>索引很神奇，可是索引不是万能，有时你建了索引也等于没用或者是白建、作无用功，为什么呢？我们看下去。</p><figure><img src="'+x+'" alt="不建议建立索引的情况1" tabindex="0" loading="lazy"><figcaption>不建议建立索引的情况1</figcaption></figure><figure><img src="'+S+'" alt="不建议建立索引的情况2" tabindex="0" loading="lazy"><figcaption>不建议建立索引的情况2</figcaption></figure><h3 id="索引不会生效的情况" tabindex="-1"><a class="header-anchor" href="#索引不会生效的情况" aria-hidden="true">#</a> 索引不会生效的情况</h3><p>所以索引不要乱建，有时建了也是白建，为什么呢？来看看下面的案例分析吧：</p><figure><img src="'+E+'" alt="索引不会生效的情况" tabindex="0" loading="lazy"><figcaption>索引不会生效的情况</figcaption></figure><h3 id="以案例来说明" tabindex="-1"><a class="header-anchor" href="#以案例来说明" aria-hidden="true">#</a> 以案例来说明</h3><h4 id="plsql优化-一个不走索引的优化案例" tabindex="-1"><a class="header-anchor" href="#plsql优化-一个不走索引的优化案例" aria-hidden="true">#</a> PLSQL优化&gt;一个不走索引的优化案例</h4><figure><img src="'+C+'" alt="不走索引的优化案例" tabindex="0" loading="lazy"><figcaption>不走索引的优化案例</figcaption></figure><p>这个例子说明了，如果你有一字参于WHERE条件查询的字段，但是它参于了运算符，因此它在ORACLE的内部执行计划中是不会走索引的，因此我们做了一个小小的变化，效率提升了多少倍？5.3倍，530%，呵呵！</p><p>以上例我们可以为建立索引作一个总结。</p><h3 id="建立索引的总结" tabindex="-1"><a class="header-anchor" href="#建立索引的总结" aria-hidden="true">#</a> 建立索引的总结</h3><figure><img src="'+O+'" alt="建立索引的总结" tabindex="0" loading="lazy"><figcaption>建立索引的总结</figcaption></figure><h2 id="table-analyze" tabindex="-1"><a class="header-anchor" href="#table-analyze" aria-hidden="true">#</a> Table Analyze</h2><figure><img src="'+T+'" alt="Table Analyze" tabindex="0" loading="lazy"><figcaption>Table Analyze</figcaption></figure><h3 id="analyze-table-vs-dbms-stats" tabindex="-1"><a class="header-anchor" href="#analyze-table-vs-dbms-stats" aria-hidden="true">#</a> Analyze Table VS DBMS_STATS</h3><figure><img src="'+y+'" alt="Analyze Table VS DBMS_STATS" tabindex="0" loading="lazy"><figcaption>Analyze Table VS DBMS_STATS</figcaption></figure><h2 id="import-export" tabindex="-1"><a class="header-anchor" href="#import-export" aria-hidden="true">#</a> Import &amp; Export</h2><p>说到Import &amp; Export命令，大家会说，哎，这个不是很简单，就是：imp username/pwd@oraid file=path 吗？嘿嘿，试想：</p><ol><li>你需要导入一个8GB左右的.dmp文件进入数据库</li><li>你需要将一个库，其中含有至少30张表并且每张表都超过1200万条记录的数据进入一个.dmp文件</li></ol><p>然后你去试试看这个耗时。</p><h3 id="import的常规做法" tabindex="-1"><a class="header-anchor" href="#import的常规做法" aria-hidden="true">#</a> Import的常规做法</h3><p>这是一个真实的案例，我们在CCC即世界著名车险公司项目中，我们定期会和CCC芝加哥总部同步一个8GB左右的.dmp文件进入我们的数据库，由于安全原因因此需要依靠.dmp交换文件的形式于零晨同步至中国的数据库，并且在T+1第二天早晨的8：00前完成同步。</p><p>于是，我们的DBA开始来了。。。。。。</p><figure><img src="'+z+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>从零晨到第二天早上8：00，硬是没有导完，一查，数据库中session已经超时了，连续2天还是这样。</p><p>于是，我们把原有的语句稍稍作了一下变化：</p><p>只是把原来的一句imp折成了2条：</p><ul><li>第一条，只导数据，不导索引，并且设置成10000条数据一次commit，同时设置了一个缓冲池</li><li>第二条，只导索引，不导数据，并且设置成10000条数据一次commit，同时设置了一个缓冲池</li></ul><p>结果让人惊叹。。。发觉最后只用了40分钟不到，两条语句全部执行完毕，完成了导入。。。其实这个原因我可以用下面2个例子来说明：</p><ol><li>一个含有8GB文件内容的目录，用FTP客户端下载，你会发觉似乎永远等不到头，几小时就这样耗着，然后你改成先把这个目录打成一个压缩包，然后再用FTP客户端下载，几十分钟就能搞定。</li><li>你用JDBC写一个FOR循环插入100万条记录，结果是ORACLE直接爆掉，而你采用批量提交，结果是惊人的！</li></ol><p>其实我们当时所做的折分，原理如同上述两个案例，是一样的道理，减少IO读写，设置缓冲，批量提交。如果你的事务太大......</p><figure><img src="'+A+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="以案例来说明plsql的优化" tabindex="-1"><a class="header-anchor" href="#以案例来说明plsql的优化" aria-hidden="true">#</a> 以案例来说明PLSQL的优化</h2><h3 id="plsql优化-select-in-与select-exists" tabindex="-1"><a class="header-anchor" href="#plsql优化-select-in-与select-exists" aria-hidden="true">#</a> PLSQL优化-SELECT IN 与SELECT EXISTS</h3><figure><img src="'+q+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这边提高了多少？光看IO就知道提高了多少了，呵 呵，很好玩吧？再来！</p><h3 id="plsql优化-select-in的几种优化" tabindex="-1"><a class="header-anchor" href="#plsql优化-select-in的几种优化" aria-hidden="true">#</a> PLSQL优化-SELECT IN的几种优化</h3><figure><img src="'+N+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="plsql优化-select-in、or、union的互转" tabindex="-1"><a class="header-anchor" href="#plsql优化-select-in、or、union的互转" aria-hidden="true">#</a> PLSQL优化-SELECT IN、OR、UNION的互转</h3><figure><img src="'+Q+`" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>看看3次修改，最后一次，提升了多少倍？11.2850-0.0261再除以0.0261=431.375，431.375倍。。。。。。一条SQL啊。。。在寸土寸金的互联网应用中，单条SQL提高了431.375倍。。。这是什么概念！！！</p><p><strong>你好讨厌！！！再来！！！</strong></p><h3 id="plsql优化-分页语句中加入索引的优化" tabindex="-1"><a class="header-anchor" href="#plsql优化-分页语句中加入索引的优化" aria-hidden="true">#</a> PLSQL优化-分页语句中加入索引的优化</h3><p>以下是一条分页语句，我们对created_date做一个索引，等。。。。。。等等等，这边的索引不是一般的索引，我们把图形化工具建的索引翻译成SQL：</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">create</span> <span class="token keyword">index</span> IDX_WAREHOUSE_CT <span class="token keyword">on</span> T_WAREHOUSE<span class="token punctuation">(</span>CREATED_DATE <span class="token keyword">DESC</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>我们这个表是一个含有1000万条记录的表，仅此一招，整个SQL查询提高了300%-340%</p><figure><img src="`+R+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="plsql优化-inner-join-vs-where" tabindex="-1"><a class="header-anchor" href="#plsql优化-inner-join-vs-where" aria-hidden="true">#</a> PLSQL优化-INNER JOIN VS WHERE</h3><figure><img src="'+B+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="plsql优化-where语句优化要点" tabindex="-1"><a class="header-anchor" href="#plsql优化-where语句优化要点" aria-hidden="true">#</a> PLSQL优化-WHERE语句优化要点</h3><p>注意下面这个例子，只是WHERE条件后的顺序上下颠倒一下，就提高了10倍的效率，呵呵。</p><figure><img src="'+U+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h4 id="where语句中选择最有效的表名顺序" tabindex="-1"><a class="header-anchor" href="#where语句中选择最有效的表名顺序" aria-hidden="true">#</a> WHERE语句中选择最有效的表名顺序</h4><figure><img src="'+k+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>好玩吧！！！再来！！！</p><figure><img src="'+w+'" alt="image-20230221152329434" tabindex="0" loading="lazy"><figcaption>image-20230221152329434</figcaption></figure><p>PLSQL优化-用UNION取代OR</p><p>看看下面这个例子吧：</p><figure><img src="'+I+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>是不是写SQL时稍微注意一下。。。这个效率。。。这个性能 。。。123%。。。123%的提高啊。</p><h2 id="plsql优化-共享sql" tabindex="-1"><a class="header-anchor" href="#plsql优化-共享sql" aria-hidden="true">#</a> PLSQL优化&gt;共享SQL</h2><p>前面我们用好几个实例说了一下PLSQL中最基本的一些性能上可以带来的提升，这边我们需要提一下 ORACLE 自带的一个缓冲 SQL 结果集命中率的工具</p><figure><img src="'+P+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>所以，我们在写SQL时要用 JAVA 的 PreparedStatement，要用:1这样的东西来做传值，因为 ORACLE 是自带 SQL 缓冲池的，另外在此要多说一句的是，虽然ORACLE10后开始带有ASM（自动内存管理），但有时ASM不是万能，对于一些大形网站，有时我们的DBA是需要手工去调整ORACLE的SGA，即：</p><figure><img src="'+v+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>因此，这对我们的ORACLE DBA来说提出了更高的要求。</p>',94);function aa(ea,ia){const i=s("ExternalLinkIcon");return l(),o("div",null,[M,a("blockquote",null,[a("p",null,[e("本文选自 TGITCIC "),a("a",V,[e("给PLSQL插上飞翔的翅膀-PLSQL优化"),n(i)]),e("。虽然文章有些老旧，但里面的一些优化知识还是很值得学习的。本文对 Oracle 数据库中的RBO、CBO、索引、WHERE条件等进行了详细讲解，并配有大量案例方便读者将优化方式快速运用到生产中去。@qiuchi")])]),a("p",null,[e("60-80% of database performance issues are related to poorly performing SQL，60-80%的数据库性能问题要归结于生产中糟糕的"),a("a",F,[e("SQL语句"),n(i)]),e("！")]),H,a("ul",null,[a("li",null,[W,a("p",null,[e("Oracle 推荐使用 COUNT(*)，因为 COUNT(1) 时，虽然数据库优化器意识到“1”是永远不会是 NULL 值，不会每行都计算一次，但是 "),G,e(" 与 "),J,e(" 用的可能不是同一个逻辑单元。"),j,a("a",X,[e("https://www.techtarget.com/searchoracle/answer/COUNT-or-COUNT-1"),n(i)])])]),K]),Y,a("p",null,[a("a",Z,[e("https://learnsql.com/blog/difference-between-count-distinct/"),n(i)])]),$])}const ra=r(D,[["render",aa],["__file","02plsql_optimization.html.vue"]]);export{ra as default};
